package com.ptms.controller; import com.ptms.dto.*; import com.ptms.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/tickets") public class TicketInventoryController{private final TicketInventoryService s;public TicketInventoryController(TicketInventoryService s){this.s=s;}@GetMapping public List<TicketDto>all(){return s.all();}@GetMapping("/remaining") public List<TicketDto>remaining(){return s.remaining();}@PostMapping("/bulk-scan") public List<TicketDto>bulk(@Valid @RequestBody BulkTicketScanRequest q){return s.bulk(q);}}
